import unittest
from config import copy_options

class CopyTests(unittest.TestCase):
    def test_nested_isolation(self):
        source={"settings":{"tags":["a"]}}
        result=copy_options(source)
        result["settings"]["tags"].append("b")
        self.assertEqual(source,{"settings":{"tags":["a"]}})
        self.assertEqual(result,{"settings":{"tags":["a","b"]}})
    def test_empty(self):
        source={}
        result=copy_options(source)
        self.assertEqual(result,{})
        self.assertIsNot(source,result)

