class ConfigStore:
    def __init__(self, initial):
        self.current = dict(initial)

    def snapshot(self):
        return self.current

    def refresh(self, load):
        self.current.clear()
        self.current.update(load())

class ConfigStore:
    def __init__(self, initial):
        self._current = dict(initial)

    def snapshot(self):
        return self._current

    def refresh(self, load):
        candidate = load()
        self._current.clear()
        self._current.update(candidate)

