import unittest
from config_store import ConfigStore

class ConfigStoreTests(unittest.TestCase):
    def test_refresh_publishes_new_values(self):
        store = ConfigStore({'mode': 'safe', 'limit': 1})
        store.refresh(lambda: {'mode': 'fast', 'limit': 2})
        self.assertEqual(store.snapshot(), {'mode': 'fast', 'limit': 2})

if __name__ == '__main__':
    unittest.main()

